    def set_user_data_of_attributes (self, *, attribute_ids, pairs = None, keys_to_delete = None):
        """Stores string values under keys in the user data of attributes, for scripts to keep their own
        state on an attribute. The given pairs are merged into what each attribute already holds: a key
        that exists gets the new value, other keys are left as they are, and the keys listed in
        keysToDelete are removed. Prefix the keys with the script's name so that scripts do not
        overwrite each other's data. User data in another layout is left unchanged and reported as an
        error. Archicad does not record this change as an undo step, so Undo does not revert it.

        Tapir command SetUserDataOfAttributes (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#SetUserDataOfAttributes

        Arguments:
        attribute_ids (attributeIds, AttributeIds, required): A list of attributes.
        pairs (UserDataPairs, optional): The key-value pairs to store on each attribute. A key the
            attribute already holds gets the new value; other keys are left as they are.
        keys_to_delete (keysToDelete, UserDataKeysToDelete, optional): The keys to remove from the user
            data. A key that is not stored is ignored. Applied after pairs.
        """
        return self.run ('SetUserDataOfAttributes', _Parameters (('attributeIds', attribute_ids), ('pairs', pairs), ('keysToDelete', keys_to_delete)))

