    def ifc_file_operation (self, *, method, ifc_file_path, overwrite = None, file_type = None, translator_name = None, elements_to_export = None, story_index = None):
        """Executes an IFC file operation: opens or merges an IFC file, or saves the project as an IFC
        file. A save can name the export translator to use, a merge the story the IFC file's first
        storey is placed on. With overwrite false a save refuses to replace an existing file.

        Tapir command IFCFileOperation (Tapir 1.2.6): https://archicad-api.com/archicad-addon/#IFCFileOperation

        Arguments:
        method (string ("save", "merge", "open"), required): The file operation method to use.
        ifc_file_path (ifcFilePath, string, required): The target IFC file to use. The save method
            overwrites an existing file, unless overwrite is false.
        overwrite (boolean, optional): Optional, true by default. Only for the save method: false
            refuses to save when a file already exists at ifcFilePath, and writes nothing.
        file_type (fileType, string ("ifc", "ifcxml", "ifczip", "ifcxmlzip"), optional): The type of the
            IFC file. The default is 'ifc'.
        translator_name (translatorName, string, optional): Only for the save method: the name of the
            IFC export translator to save with, as GetIFCExportTranslators lists them. Without it the save
            runs with the translator Archicad would offer in its own Save dialog. Needs a fileType of ifc or
            ifczip (ifc or ifcxml on Archicad 25 and 26).
        elements_to_export (elementsToExport, IFCElementsToExport, optional): Only for the save method,
            and only together with translatorName. The default is VisibleElementsOnAllStories.
        story_index (storyIndex, integer, optional): Only for the merge method: the story the first
            storey of the IFC file is placed on, the IFC's other storeys follow on the stories above it.
            Without it Archicad uses the active story of the floor plan. The active story and the current
            window are restored after the merge. See GetStories for the val...
        """
        return self.run ('IFCFileOperation', _Parameters (('method', method), ('ifcFilePath', ifc_file_path), ('overwrite', overwrite), ('fileType', file_type), ('translatorName', translator_name), ('elementsToExport', elements_to_export), ('storyIndex', story_index)))

