    def add_files_to_embedded_library (self, *, files, overwrite_existing = None):
        """Adds the given files into the embedded library. With the overwriteExisting flag an embedded
        library item already existing on an outputPath is replaced (Archicad 27 or newer).

        Tapir command AddFilesToEmbeddedLibrary (Tapir 1.2.2): https://archicad-api.com/archicad-addon/#AddFilesToEmbeddedLibrary

        Arguments:
        files (LibraryFileAdditions, required): A list of library file additions to the embedded library
        overwrite_existing (overwriteExisting, boolean, optional): Optional. When true, an embedded
            library item already existing on an outputPath is deleted first, so the newly added file
            replaces the loaded library part. By default false: the existing loaded part stays in use.
            Requires Archicad 27 or newer.
        """
        return self.run ('AddFilesToEmbeddedLibrary', _Parameters (('files', files), ('overwriteExisting', overwrite_existing)))

    def delete_embedded_library_items (self, *, embedded_library_items):
        """Deletes the given items from the embedded library. The path of an item is the same relative path
        that AddFilesToEmbeddedLibrary takes as outputPath. Available from Archicad 27.

        Tapir command DeleteEmbeddedLibraryItems (Tapir 1.6.0): https://archicad-api.com/archicad-addon/#DeleteEmbeddedLibraryItems

        Arguments:
        embedded_library_items (embeddedLibraryItems, array of EmbeddedLibraryItem, required): A list of
            embedded library items to delete.
        """
        return self.run ('DeleteEmbeddedLibraryItems', _Parameters (('embeddedLibraryItems', embedded_library_items)))

    def create_library_parts (self, *, library_parts, overwrite_existing = None):
        """Creates GDL library parts in the embedded library from their scripts (master, 2D, 3D, parameter,
        interface, properties) and parameter definitions, under the given parent subtype. The new parts
        are placeable right away, e.g. with CreateObjects. With the overwriteExisting flag an embedded
        library item already existing on the path of a new part is replaced (Archicad 27 or newer).

        Tapir command CreateLibraryParts (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#CreateLibraryParts

        Arguments:
        library_parts (libraryParts, array of LibraryPartData, required): The library parts to create in
            the embedded library.
        overwrite_existing (overwriteExisting, boolean, optional): Optional. When true, an embedded
            library item already existing on the path of a new library part is deleted first, so the new one
            replaces the loaded library part. By default false: creating on an existing path fails. Requires
            Archicad 27 or newer.
        """
        return self.run ('CreateLibraryParts', _Parameters (('libraryParts', library_parts), ('overwriteExisting', overwrite_existing)))

    def create_folder_in_embedded_library (self, *, folder_path):
        """Creates a folder, with any missing parent folders, inside the embedded library. The folderPath
        is relative to the embedded library, like the outputPath of AddFilesToEmbeddedLibrary.

        Tapir command CreateFolderInEmbeddedLibrary (Tapir 1.7.3): https://archicad-api.com/archicad-addon/#CreateFolderInEmbeddedLibrary

        Arguments:
        folder_path (folderPath, string, required): The path of the folder relative to the embedded
            library, for example 'Office/Doors'. Missing parent folders are created too; folders that
            already exist are kept.
        """
        return self.run ('CreateFolderInEmbeddedLibrary', _Parameters (('folderPath', folder_path)))

    def copy_files_into_embedded_library (self, *, files, target_folder = None, overwrite_if_exists = None):
        """Copies the given files, keeping their names, into a folder of the embedded library with one
        library operation. The target folder is created when it is missing. With overwriteIfExists an
        item of the same name in that folder is replaced.

        Tapir command CopyFilesIntoEmbeddedLibrary (Tapir 1.7.3): https://archicad-api.com/archicad-addon/#CopyFilesIntoEmbeddedLibrary

        Arguments:
        files (array of EmbeddedLibraryFile, required): The files to copy. Each keeps its file name
            inside the target folder.
        target_folder (targetFolder, string, optional): Optional. The folder relative to the embedded
            library to copy the files into, for example 'Office/Doors'. Missing folders are created. By
            default the root of the embedded library.
        overwrite_if_exists (overwriteIfExists, boolean, optional): Optional. When true, an item with
            the same name in the target folder is replaced. By default false.
        """
        return self.run ('CopyFilesIntoEmbeddedLibrary', _Parameters (('files', files), ('targetFolder', target_folder), ('overwriteIfExists', overwrite_if_exists)))

