    def get_mep_preference_table_rows (self, *, table_id, keys):
        """Gets rows of a segment, branch, elbow or (from Archicad 29) transition preference table by their
        key (the reference ids and, for branch and elbow rows from Archicad 29, the angle): whether the
        row is valid and its values (diameters, wall thickness, radius, length, angle, branch offset,
        connection length, description), and whether the table exists. Rectangular duct and cable
        carrier segment tables only give whether they exist, as their rows have no key. On Archicad 27,
        which has one kind of preference table, a row is found by its shape and index and has a value
        and a description; the table's name and number of rows per shape are returned too. Available
        from Archicad 27.

        Tapir command GetMEPPreferenceTableRows (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#GetMEPPreferenceTableRows

        Arguments:
        table_id (tableId, MEPPreferenceTableId, required): The guid of a preference table, as returned
            by GetMEPPreferenceTables (the branch, elbow and transition tables with includeFittingTables): a
            pipe or circular duct segment table, a branch or elbow table of the Piping or Ventilation
            domain, or, from Archicad 29, a transition table. Rectangular duct...
        keys (array of MEPPreferenceRowKey, required): The keys of the rows to get.
        """
        return self.run ('GetMEPPreferenceTableRows', _Parameters (('tableId', table_id), ('keys', keys)))

    def set_mep_preference_table_rows (self, *, table_id, rows):
        """Sets the given values of rows of a segment, branch, elbow or (from Archicad 29) transition
        preference table, found by their key (the reference ids and, for branch and elbow rows from
        Archicad 29, the angle). Only the given values are changed, in one undo step. On Archicad 27 a
        row is found by its shape and index, its value and description are set, and its index after the
        call is returned; the keys give the indices before the call. Available from Archicad 27.

        Tapir command SetMEPPreferenceTableRows (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#SetMEPPreferenceTableRows

        Arguments:
        table_id (tableId, MEPPreferenceTableId, required): The guid of a preference table, as returned
            by GetMEPPreferenceTables (the branch, elbow and transition tables with includeFittingTables): a
            pipe or circular duct segment table, a branch or elbow table of the Piping or Ventilation
            domain, or, from Archicad 29, a transition table. Rectangular duct...
        rows (array of MEPPreferenceRowUpdate, required): The rows to change. Only the given values are
            set.
        """
        return self.run ('SetMEPPreferenceTableRows', _Parameters (('tableId', table_id), ('rows', rows)))

    def add_mep_preference_table_rows (self, *, table_id, rows):
        """Adds rows with the given keys and optionally values to a branch, elbow or transition preference
        table and returns their index, in one undo step. Branch tables from Archicad 28, elbow and
        transition tables from Archicad 29; segment tables have a row for each reference id. On Archicad
        27 a row is added to the list of the given shape of any preference table, and the index of each
        new row after the call is returned. Available from Archicad 27.

        Tapir command AddMEPPreferenceTableRows (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#AddMEPPreferenceTableRows

        Arguments:
        table_id (tableId, MEPPreferenceTableId, required): The guid of a preference table, as returned
            by GetMEPPreferenceTables (the branch, elbow and transition tables with includeFittingTables): a
            pipe or circular duct segment table, a branch or elbow table of the Piping or Ventilation
            domain, or, from Archicad 29, a transition table. Rectangular duct...
        rows (array of MEPPreferenceRowAddition, required): The rows to add, with their key and
            optionally their values. Branch tables from Archicad 28, elbow and transition tables from
            Archicad 29. Segment tables have a row for each reference id, so no row can be added to them.
            Archicad 27: the key has the shape only, the table gives the index.
        """
        return self.run ('AddMEPPreferenceTableRows', _Parameters (('tableId', table_id), ('rows', rows)))

    def delete_mep_preference_table_rows (self, *, table_id, keys):
        """Deletes rows of a segment, branch, elbow or (from Archicad 29) transition preference table by
        their key (the reference ids and, for branch and elbow rows from Archicad 29, the angle), in one
        undo step. The rows of segment tables, and of the elbow tables of Archicad 28, are emptied
        instead. On Archicad 27 a row is found by its shape and index. Available from Archicad 27.

        Tapir command DeleteMEPPreferenceTableRows (Tapir 1.8.0): https://archicad-api.com/archicad-addon/#DeleteMEPPreferenceTableRows

        Arguments:
        table_id (tableId, MEPPreferenceTableId, required): The guid of a preference table, as returned
            by GetMEPPreferenceTables (the branch, elbow and transition tables with includeFittingTables): a
            pipe or circular duct segment table, a branch or elbow table of the Piping or Ventilation
            domain, or, from Archicad 29, a transition table. Rectangular duct...
        keys (array of MEPPreferenceRowKey, required): The keys of the rows to delete. Segment tables,
            and the elbow tables of Archicad 28, have a row for each reference id, which is emptied instead.
            Archicad 27: the indices are those before the call; the rows are deleted from the highest index
            down.
        """
        return self.run ('DeleteMEPPreferenceTableRows', _Parameters (('tableId', table_id), ('keys', keys)))

