    def pick_attribute (self, *, attribute_type, attribute_id = None, title = None):
        """Opens a small dialog with Archicad's attribute picker for the given attribute type (layer,
        building material, composite, profile or surface; fill and line from Archicad 27), waits for the
        user and returns the chosen attribute, or cancelled. Available from Archicad 26.

        Tapir command PickAttribute (Tapir 2.0.0): https://archicad-api.com/archicad-addon/#PickAttribute

        Arguments:
        attribute_type (attributeType, string ("Layer", "BuildingMaterial", "Composite", "Profile",
            "Surface", "Fill", "Line"), required): The type of the attribute to pick. Fill and Line need
            Archicad 27 or newer. Composite lists the composites only.
        attribute_id (attributeId, AttributeId, optional): The attribute selected when the dialog opens.
            Without it the picker starts empty and OK is enabled once the user has picked an attribute.
        title (string, optional): The title of the dialog. Default: Pick Attribute.
        """
        return self.run ('PickAttribute', _Parameters (('attributeType', attribute_type), ('attributeId', attribute_id), ('title', title)))

    def pick_attribute_folder (self, *, attribute_type, title = None):
        """Opens a small dialog with Archicad's attribute folder picker for the given attribute type, waits
        for the user and returns the chosen folder as its path from the root folder, or cancelled.
        Available from Archicad 26.

        Tapir command PickAttributeFolder (Tapir 2.0.0): https://archicad-api.com/archicad-addon/#PickAttributeFolder

        Arguments:
        attribute_type (attributeType, string ("Layer", "BuildingMaterial", "Composite", "Profile",
            "Surface", "Fill", "Line"), required): The type of the attributes whose folders the picker
            lists. Fill and Line need Archicad 27 or newer.
        title (string, optional): The title of the dialog. Default: Pick Attribute Folder.
        """
        return self.run ('PickAttributeFolder', _Parameters (('attributeType', attribute_type), ('title', title)))

